//! `blade.lock` — the exact versions a project was installed with.
//!
//! ```toml
//! # Generated by blade. Do not edit.
//! version = 1
//!
//! [[package]]
//! name = "web"
//! version = "12.3.1"
//! source = "git+https://example.org/web"
//! commit = "4f1c…"
//! checksum = "sha256:9a0e…"
//! dependencies = ["json"]
//! ```

use std::collections::BTreeMap;
use std::path::Path;

use crate::version::Version;

/// File name of the lock, next to `blade.toml`.
pub const LOCK: &str = "blade.lock";

/// Installed packages by name.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Lock {
    pub packages: BTreeMap<String, Locked>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Locked {
    pub version: Version,
    /// `git+<url>` or `path+<directory>`.
    pub source: String,
    /// The commit of a git package.
    pub commit: Option<String>,
    /// `sha256:<hex>` of the installed files.
    pub checksum: String,
    pub dependencies: Vec<String>,
}

impl Lock {
    /// The lock of the project at `root`; no file — an empty lock.
    pub fn read(root: &Path) -> Result<Lock, String> {
        let file = root.join(LOCK);
        let text = match std::fs::read_to_string(&file) {
            Ok(text) => text,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                return Ok(Lock::default());
            }
            Err(error) => return Err(format!("cannot read {}: {error}", file.display())),
        };
        Lock::parse(&text).map_err(|error| format!("{}: {error}", file.display()))
    }

    pub fn parse(text: &str) -> Result<Lock, String> {
        let table: toml::Table = text
            .parse()
            .map_err(|error: toml::de::Error| error.message().to_string())?;
        let mut lock = Lock::default();
        let packages = match table.get("package") {
            None => return Ok(lock),
            Some(toml::Value::Array(packages)) => packages,
            Some(_) => return Err("[[package]] must be an array of tables".to_string()),
        };
        for package in packages {
            let package = package.as_table().ok_or("[[package]] must be a table")?;
            let text = |key: &str| package.get(key).and_then(toml::Value::as_str);
            let name = text("name").ok_or("a package has no name")?;
            let version = text("version")
                .and_then(Version::parse)
                .ok_or_else(|| format!("package \"{name}\" has no valid version"))?;
            let dependencies = package
                .get("dependencies")
                .and_then(toml::Value::as_array)
                .map(|names| {
                    names
                        .iter()
                        .filter_map(toml::Value::as_str)
                        .map(str::to_string)
                        .collect()
                })
                .unwrap_or_default();
            lock.packages.insert(
                name.to_string(),
                Locked {
                    version,
                    source: text("source")
                        .ok_or_else(|| format!("package \"{name}\" has no source"))?
                        .to_string(),
                    commit: text("commit").map(str::to_string),
                    checksum: text("checksum").unwrap_or_default().to_string(),
                    dependencies,
                },
            );
        }
        Ok(lock)
    }

    pub fn text(&self) -> String {
        let quote = |text: &str| toml::Value::String(text.to_string()).to_string();
        let mut out = String::from("# Generated by blade. Do not edit.\nversion = 1\n");
        for (name, package) in &self.packages {
            out.push_str("\n[[package]]\n");
            out.push_str(&format!("name = {}\n", quote(name)));
            out.push_str(&format!(
                "version = {}\n",
                quote(&package.version.to_string())
            ));
            out.push_str(&format!("source = {}\n", quote(&package.source)));
            if let Some(commit) = &package.commit {
                out.push_str(&format!("commit = {}\n", quote(commit)));
            }
            out.push_str(&format!("checksum = {}\n", quote(&package.checksum)));
            let names: Vec<String> = package
                .dependencies
                .iter()
                .map(|name| quote(name))
                .collect();
            out.push_str(&format!("dependencies = [{}]\n", names.join(", ")));
        }
        out
    }

    pub fn write(&self, root: &Path) -> Result<(), String> {
        let file = root.join(LOCK);
        std::fs::write(&file, self.text())
            .map_err(|error| format!("cannot write {}: {error}", file.display()))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn lock_text_round_trips() {
        let mut lock = Lock::default();
        lock.packages.insert(
            "web".to_string(),
            Locked {
                version: Version::parse("12.3.1").unwrap(),
                source: "git+https://example.org/web \"x\"".to_string(),
                commit: Some("abc".to_string()),
                checksum: "sha256:00".to_string(),
                dependencies: vec!["json".to_string()],
            },
        );
        lock.packages.insert(
            "json".to_string(),
            Locked {
                version: Version::parse("1.0.0").unwrap(),
                source: "path+/home/user/json".to_string(),
                commit: None,
                checksum: "sha256:11".to_string(),
                dependencies: Vec::new(),
            },
        );
        assert_eq!(Lock::parse(&lock.text()).unwrap(), lock);
        assert_eq!(Lock::parse("version = 1\n").unwrap(), Lock::default());
    }
}
